import { ProviderRpcError } from './types.js';

/** Published identity hints, not proof of vendor identity or network support. */
export const ROBINHOOD_WALLET: Readonly<{id: string; name: string; rdns: string; walletConnectId: string; mobileLink: string; downloadUrl: string; iconUrl: string}> = Object.freeze({
  id: 'robinhood',
  name: 'Robinhood Wallet',
  rdns: 'com.robinhood.wallet',
  walletConnectId: '8837dd9413b1d9b585ee937d27a816590248386d9dbf59f5cd3422dbbb65683e',
  mobileLink: 'robinhood-wallet://',
  downloadUrl: 'https://robinhood.com/wallet/',
  iconUrl: 'data:image/png;base64,',
});

export function getRobinhoodUri(uri: string): string {
  // Pairing secrets stay local: never submit them to a QR or redirect service.
  if (typeof uri !== 'string' || !/^wc:[a-f0-9]{64}@2\?/.test(uri)) {
    throw new ProviderRpcError(-32602, 'Invalid WalletConnect pairing link.');
  }
  const parsed = new URL(uri);
  if (parsed.searchParams.get('relay-protocol') !== 'irn' || !/^[a-f0-9]{64}$/.test(parsed.searchParams.get('symKey') ?? '')) {
    throw new ProviderRpcError(-32602, 'Invalid WalletConnect pairing link.');
  }
  return `${ROBINHOOD_WALLET.mobileLink}wc?uri=${encodeURIComponent(uri)}`;
}
